import {TYPE_NAMES,STATUS_NAMES,LABELS,ENTITY_TYPES,icon,esc,pct,copy,uid,blankAnnotation,validateTask,reviewStats,dateTime,time,mergeHistory} from './core.js';
import {Store,mediaURL} from './storage.js';
import {PROJECTS} from './data.js';
import {Editor} from './editor.js';
import {download,exportZip,exportActions,manifest,importPackage,csv,coco} from './io.js';

const app={store:new Store(),tasks:[],profile:{name:'标注员',group:'个人项目',number:''},page:'dashboard',project:'imports',taskId:null,statusFilter:'all',typeFilter:'all',search:'',reviewFilter:'submitted',reviewId:null,pending:new Set()};
const $=s=>document.querySelector(s);
let toastTimer,editor=null;
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?6500:3800)}
function modal(title,body,footer='',wide=false){
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭窗口">${icon('close',18)}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;
 app.previousFocus=document.activeElement;setTimeout(()=>$('#modal-root button, #modal-root input, #modal-root select')?.focus(),0);
}
function closeModal(){if(app.busy)return;$('#modal-root').innerHTML='';app.previousFocus?.focus?.()}
function confirmModal(title,text,callback){modal(title,`<p>${esc(text)}</p>`,`<button class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" id="confirm-action">确认</button>`);$('#confirm-action').onclick=async()=>{closeModal();await callback()}}
function busy(title,text){app.busy=true;modal(title,`<p>${esc(text)}</p><div class="load-progress"><i></i></div>`);$('#modal-root [data-action="close-modal"]').disabled=true}
function unbusy(){app.busy=false;closeModal()}
const tasksFor=id=>app.tasks.filter(t=>t.project===id);
const project=id=>PROJECTS.find(p=>p.id===id)||PROJECTS.at(-1);
const countAnn=t=>t.type==='image'?(t.goal==='classification'?(t.annotation.scene?1:0):t.annotation.boxes.length):t.type==='video'?t.annotation.tracks.length+(t.annotation.actions?.length||0):t.type==='audio'?t.annotation.segments.length:t.annotation.entities.length+(t.annotation.intent?1:0);
const done=t=>['submitted','approved'].includes(t.status);
const status=t=>`<span class="status ${t.status}">${STATUS_NAMES[t.status]||'未知'}</span>`;
function persistTask(task){
 const old=app.tasks.find(t=>t.id===task.id);task.history=mergeHistory(old?.history,task.history);if(old?.status==='new'&&task.status==='draft')task.history.push({at:new Date().toISOString(),action:'start',note:'开始标注',by:app.profile.name});
 const i=app.tasks.findIndex(t=>t.id===task.id);if(i>=0)app.tasks[i]=copy(task);else app.tasks.push(copy(task));
 const badge=$('button[data-page="review"] .count');if(badge)badge.textContent=app.tasks.filter(t=>t.status==='submitted').length;
 const label=$('#save-state');if(label)label.textContent='正在保存…';
 const p=app.store.putTask(copy(task)).then(()=>{if(label&&document.contains(label))label.textContent='已保存 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'});app.saveError=false}).catch(e=>{app.saveError=true;if(label)label.textContent='保存失败';toast('本地保存失败，请立即导出备份：'+e.message,true);throw e}).finally(()=>app.pending.delete(p));app.pending.add(p);return p;
}
async function flush(){await Promise.all([...app.pending])}
function navHTML(){return `<aside class="sidebar" id="sidebar"><a class="brand" href="#" data-action="nav" data-page="dashboard"><span class="brand-symbol"></span><span class="brand-word"><strong>标注工坊</strong><small>ANNOTATION LAB</small></span></a><div class="nav-label">ANNOTATION SPACE</div><nav class="nav">${[['dashboard','grid','项目工作台'],['workbench','box','标注工作区'],['review','review','质量复核'],['exports','export','交付中心'],['assessment','review','实操考核']].map(([id,ic,name])=>`<button data-action="nav" data-page="${id}" class="${app.page===id||id==='dashboard'&&app.page==='project'?'active':''}" title="${name}">${icon(ic,18)}<span>${name}</span>${id==='review'?`<span class="count">${app.tasks.filter(t=>t.status==='submitted').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="course-mini"><span class="eyebrow">YOUR ANNOTATIONS</span><strong>四种数据 · 一个工作台</strong><small>导入素材，标注并交付</small></div><nav class="nav"><button data-action="guide" title="操作指南">${icon('help',18)}<span>操作指南</span></button></nav><button class="profile-btn" data-action="profile" title="编辑标注员信息"><span class="avatar">${esc((app.profile.name||'标注员').slice(0,1))}</span><span><strong>${esc(app.profile.name)}</strong><small>${esc(app.profile.group||'个人项目')}</small></span>${icon('chevron',13)}</button></div></aside>`}
function shell(){const names={dashboard:'项目工作台',project:project(app.project).title,workbench:'标注工作区',review:'质量复核',exports:'交付中心'};
 document.body.classList.toggle('workspace',app.page==='workbench');
 $('#app').innerHTML=navHTML()+`<div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-only" data-action="menu" aria-label="展开导航">${icon('menu',18)}</button><span>标注空间</span><span>/</span><strong>${names[app.page]}</strong></div><div class="top-actions"><span class="local-pill">本地标注 · 自动保存</span><button class="icon-btn" data-action="import-package" title="导入作业包" aria-label="导入作业包">${icon('folder',18)}</button><button class="icon-btn" data-action="guide" title="操作指南" aria-label="操作指南">${icon('help',18)}</button></div></header><main class="content" id="content"></main></div>`;
}
async function navigate(page,params={}){
 try{await flush()}catch{return}editor?.destroy();editor=null;Object.assign(app,params);app.page=page;if(page!=='workbench')window.scrollTo(0,0);shell();
 if(page==='dashboard')renderDashboard();else if(page==='project')renderProject();else if(page==='review')renderReview();else if(page==='exports')renderExports();else await renderWorkbench();
}
function pageHeader(kicker,title,subtitle,actions=''){return `<div class="page-header"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="hero-actions">${actions}</div>`:''}</div>`}
function cover(p){const types=[...new Set(tasksFor(p.id).map(t=>t.type))];return `<div class="project-cover mixed">${(types.length?types:['image','video','audio','text']).map(type=>`<div class="mixed-piece">${icon(type,27)}</div>`).join('')}<span class="cover-badge">${icon('folder',11)}本地素材项目</span></div>`}
function projectCard(p){const ts=tasksFor(p.id),n=ts.filter(done).length;return `<button class="project-card" data-action="project" data-project="${p.id}">${cover(p)}<div class="project-body"><div class="project-meta"><span>${p.day?'DAY 0'+p.day:'MY MATERIALS'} <span class="dot">/</span> ${p.tag}</span><span>${ts.length} 个素材</span></div><h3>${p.title}</h3><p>${p.description}</p></div><div class="project-foot"><div class="between"><span>已提交 ${n} / ${ts.length}</span>${icon('arrow',16)}</div><div class="progress"><i style="width:${pct(n,ts.length)}%"></i></div></div></button>`}
function renderDashboard(){const total=app.tasks.length,submitted=app.tasks.filter(done).length,rework=app.tasks.filter(t=>t.status==='rework').length,recent=app.tasks.filter(t=>t.updatedAt).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,5);
 $('#content').innerHTML=pageHeader('MULTIMODAL ANNOTATION','开始今天的标注工作','导入自己的图像、视频、音频与文字，完成标注、质量复核和结果交付。',`<button class="btn secondary" data-action="import-media">${icon('plus',16)}导入素材</button><button class="btn primary" data-action="${total?'continue':'import-package'}">${total?'继续标注':'导入作业包'}${icon('arrow',15)}</button>`)+
 `<div class="stats-row">${[[total,'标注素材','个','folder'],[submitted,'已提交作业','个','check'],[rework,'需要返修','个','review'],[app.tasks.filter(t=>t.status==='approved').length,'复核通过','个','check']].map(([n,title,unit,ic])=>`<div class="stat"><div><small>${title}</small><strong>${n}<em>${unit}</em></strong></div><span class="stat-icon">${icon(ic,20)}</span></div>`).join('')}</div><div class="training-banner"><div class="flex"><span class="flag">${icon('folder',19)}</span><div><strong>从自己的素材开始</strong><p>支持图片、视频、音频和 TXT；标注自动保存到当前浏览器，可导出完整 ZIP 在另一台电脑继续。</p></div></div><button class="btn secondary small" data-action="import-media">导入素材${icon('plus',13)}</button></div><div class="section-title"><h2>标注项目 <small class="muted" style="font-weight:400;margin-left:9px">ANNOTATION PROJECTS</small></h2><span class="tiny muted">图像 · 视频 · 音频 · 文字</span></div><div class="project-grid">${total?PROJECTS.filter(p=>tasksFor(p.id).length).map(projectCard).join(''):''}<button class="project-card import-card" data-action="import-media">${icon('plus',25)}<h3>导入自己的素材</h3><p>PNG / JPG / WebP、MP4 / WebM、音频或 TXT</p></button></div><div class="section-title"><h2>最近标注</h2>${total?`<button class="btn ghost small" data-action="project" data-project="imports">查看全部${icon('arrow',13)}</button>`:''}</div><div class="panel table-wrap">${recent.length?taskTable(recent):`<div class="empty">${icon('box',28)}还没有标注记录。<br>导入自己的素材，开始第一项标注。</div>`}</div>`;
}
function taskTable(tasks,review=false){return `<table class="data-table"><thead><tr><th>素材名称</th><th>类型</th><th>标注</th><th>状态</th><th>${review?'提交人':'最近保存'}</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr ${review?`class="review-row ${app.reviewId===t.id?'active':''}"`:''}><td><div class="flex">${t.type==='image'&&!t.blobId?`<img class="table-thumb" src="${esc(t.posterSrc||t.src)}" alt="" loading="lazy">`:''}<span class="task-name">${esc(t.name)}${t.annotation.uncertain?' <span class="tag">疑难</span>':''}</span></div></td><td><span class="type-icon">${icon(t.type,15)}${TYPE_NAMES[t.type]}</span></td><td>${countAnn(t)} 项</td><td>${status(t)}</td><td class="tiny muted">${review?esc(t.originLearner||app.profile.name):dateTime(t.updatedAt)}</td><td><button class="btn ghost small" data-action="${review?'review-select':'open-task'}" data-id="${esc(t.id)}">${review?'复核':'打开'}${icon('arrow',13)}</button></td></tr>`).join('')}</tbody></table>`}
function filteredTasks(){return tasksFor(app.project).filter(t=>(app.statusFilter==='all'||t.status===app.statusFilter)&&(app.typeFilter==='all'||t.type===app.typeFilter)&&(!app.search||t.name.toLowerCase().includes(app.search.toLowerCase())||t.id.includes(app.search)))}
function renderProject(){const p=project(app.project),ts=tasksFor(p.id),types=[...new Set(ts.map(t=>t.type))];$('#content').innerHTML=pageHeader('PROJECT / CUSTOM',p.title,p.goal,`<button class="btn secondary" data-action="standards">${icon('book',15)}标注规范</button><button class="btn primary" data-action="open-project-first">开始标注${icon('arrow',15)}</button>`)+`<div class="filters"><div class="flex" style="flex-wrap:wrap"><div class="tabs">${[['all','全部'],['new','未开始'],['draft','标注中'],['submitted','待复核'],['rework','待返修'],['approved','已通过']].map(([v,n])=>`<button data-action="status-filter" data-value="${v}" class="${app.statusFilter===v?'active':''}">${n}</button>`).join('')}</div>${types.length>1?`<select id="type-filter" aria-label="筛选素材类型"><option value="all">全部类型</option>${types.map(v=>`<option value="${v}" ${app.typeFilter===v?'selected':''}>${TYPE_NAMES[v]}</option>`).join('')}</select>`:''}</div><div class="search">${icon('search',16)}<input id="task-search" value="${esc(app.search)}" placeholder="搜索素材名称或 ID" aria-label="搜索素材"></div></div><div class="panel table-wrap" id="project-table">${filteredTasks().length?taskTable(filteredTasks()):'<div class="empty">没有符合条件的素材。</div>'}</div><p class="helper" style="margin-top:15px">共 ${ts.length} 个素材，${ts.filter(done).length} 个已提交，${ts.filter(t=>t.status==='rework').length} 个待返修。</p>`;}

function stripHTML(tasks,id){return `<aside class="task-strip"><div class="strip-head"><strong>素材列表</strong><span>${tasks.length} 项</span></div><div class="strip-list">${tasks.map((t,i)=>`<button class="strip-task ${id===t.id?'active':''}" data-action="open-task" data-id="${esc(t.id)}">${t.type==='image'&&!t.blobId?`<img src="${esc(t.posterSrc||t.src)}" alt="" loading="lazy">`:`<span class="strip-icon">${icon(t.type,17)}</span>`}<span><span class="name">${String(i+1).padStart(2,'0')} ${esc(t.name)}</span>${status(t)}</span></button>`).join('')}</div><div class="strip-foot"><button class="btn secondary small" data-action="project" data-project="${app.project}">${icon('left',13)}返回项目</button></div></aside>`}
async function renderWorkbench(){
 let task=app.tasks.find(t=>t.id===app.taskId);if(!task)task=tasksFor(app.project).find(t=>!done(t))||tasksFor(app.project)[0]||app.tasks[0];if(!task){await navigate('dashboard');return}app.taskId=task.id;app.project=task.project;app.store.setting('lastTask',task.id).catch(()=>{});const ts=tasksFor(app.project),idx=ts.findIndex(t=>t.id===task.id);
 $('#content').innerHTML=`<section class="workbench"><div class="wb-top"><div class="wb-title"><h2>${esc(task.name)} <span class="tag">${TYPE_NAMES[task.type]}</span></h2><p><span>${project(task.project).title}</span><span>${idx+1} / ${ts.length}</span><span id="wb-status">${status(task)}</span></p></div><div class="flex"><span class="save-state" id="save-state">${task.updatedAt?'已保存 '+dateTime(task.updatedAt):'尚未修改'}</span><button class="btn secondary small" data-action="standards" title="标注规范">${icon('book',14)}规范</button></div></div><div class="editor-root" id="editor-root"></div><footer class="wb-bottom"><span class="shortcut-list" ${['classification','actions'].includes(task.goal)?'style="visibility:hidden"':''}><span><kbd>B</kbd> 画框</span><span><kbd>V</kbd> 选择</span><span><kbd>⌘ Z</kbd> 撤销</span></span><div class="flex"><button class="btn secondary small" data-action="prev-task" ${idx===0?'disabled':''}>${icon('left',13)}上一项</button><button class="btn secondary small" data-action="next-task" ${idx===ts.length-1?'disabled':''}>下一项${icon('chevron',13)}</button></div><div class="flex"><button class="btn secondary small" data-action="save-task">${icon('save',14)}保存</button><button class="btn primary small" data-action="submit-task" ${['submitted','approved'].includes(task.status)?'disabled':''}>${icon('check',14)}提交复核</button></div></footer></section>`;
 editor=new Editor($('#editor-root'),task,{store:app.store,listHTML:stripHTML(ts,task.id),onChange:t=>{persistTask(t).catch(()=>{});const s=$('#wb-status');if(s)s.innerHTML=status(t);const strip=$(`.strip-task[data-id="${CSS.escape(t.id)}"] .status`);if(strip)strip.outerHTML=status(t)},toast,reference:referenceModal});await editor.mount();
}
async function submitTask(){if(!editor)return;if(!editor.mediaReady&&!editor.a.uncertain){toast('请等待素材加载完成后再提交。',true);return}const t=copy(editor.task),errors=validateTask(t);if(errors.length){modal('提交前请检查',`<div class="validation-errors">${errors.map(e=>`<div>• ${esc(e)}</div>`).join('')}</div><p>补齐后即可重新提交，当前草稿已经自动保存。</p>`,`<button class="btn primary" data-action="close-modal">返回修改</button>`);return}
 t.status='submitted';t.updatedAt=new Date().toISOString();t.submittedAt=t.updatedAt;t.history.push({at:t.updatedAt,action:'submit',by:app.profile.name,note:t.annotation.uncertain?'提交疑难样本：'+t.annotation.issue:'提交复核'});await persistTask(t);await navigate('workbench',{taskId:t.id});toast('已提交到本地待复核列表，导出作业包后可交给复核人。')}
function standardsModal(){modal('标注操作规范',`<h3>图像分类与目标边界</h3><p>先选择场景和目标类别，拖动绘制矩形框，或用 P 绘制多边形。按可见边界标注，检查漏标、重复和遮挡。可在右侧添加自定义类别与对象描述。</p><h3>视频动作与对象轨迹</h3><p>动作模式在时间轴拖出起止范围，填写人物、动作、对象和描述。I/O 标记起止，左右键逐帧。物体轨迹沿用稳定对象 ID，填写真实固定帧率，并在不同帧更新目标框。关键帧之间使用线性插值，需要回看核对。</p><h3>音频分段与转写</h3><p>拖动真实波形创建片段，按自然句或说话人变化分段。填写原文转写与说话人，回放选段检查边界；听不清时标记并备注。</p><h3>文字意图与实体</h3><p>意图分为查询、变更、取消、其他；选择原文中的日期、时间或地点创建实体，保留原文和字符位置，避免重叠区段。</p><h3>复核与交付</h3><p>完成后提交复核，记录具体问题与定位，退回返修或通过。历史记录随作业包保存；跨电脑交付请导出含素材的完整 ZIP。</p>`,`<button class="btn primary" data-action="close-modal">已阅读</button>`,true)}
function referenceModal(t){const truth=t.truth;let content='<p>此素材没有附带参考标注，请按项目规范复核。</p>';if(truth)content=`<p>此参考由导入的作业包提供，请结合原始素材核对。</p><div class="reference-box">${esc(JSON.stringify(truth,null,2))}</div>`;modal('参考标注',content,`<button class="btn primary" data-action="close-modal">返回标注</button>`)}
function renderReview(){const stats=reviewStats(app.tasks),candidates=app.tasks.filter(t=>app.reviewFilter==='all'?['submitted','rework','approved'].includes(t.status):t.status===app.reviewFilter);if(!candidates.some(t=>t.id===app.reviewId))app.reviewId=candidates[0]?.id||null;const selected=app.tasks.find(t=>t.id===app.reviewId);
 $('#content').innerHTML=pageHeader('QUALITY REVIEW','让每一条修改都有依据','本地复核标注。复核人可导入标注作业包，查看原素材、记录意见并退回或通过。',`<button class="btn secondary" data-action="import-package">${icon('upload',15)}导入标注作业</button>`)+`<div class="stats-row">${[[app.tasks.filter(t=>t.status==='submitted').length,'待复核'],[stats.checked,'已复核'],[stats.rework,'退回返修'],[stats.rate===null?'—':(stats.rate*100).toFixed(1)+'%','本次退回占比']].map(([n,title])=>`<div class="stat"><div><small>${title}</small><strong>${n}</strong></div></div>`).join('')}</div><div class="filters"><div class="tabs">${[['submitted','待复核'],['rework','已退回'],['approved','已通过'],['all','全部复核']].map(([v,n])=>`<button class="${app.reviewFilter===v?'active':''}" data-action="review-filter" data-value="${v}">${n}</button>`).join('')}</div><span class="tiny muted">退回占比按本地已复核样本计算，不是完整数据集的错误率。</span></div><div class="review-grid"><div class="panel table-wrap">${candidates.length?taskTable(candidates,true):`<div class="empty">${icon('review',30)}还没有${app.reviewFilter==='submitted'?'待复核':'符合条件的'}作业。<br>先提交标注，或导入学员导出的 ZIP 作业包。</div>`}</div>${selected?reviewForm(selected):'<div class="panel review-form"><h3>复核顺序</h3><ul class="check-list"><li>1. 打开原素材与标注</li><li>2. 按规范检查标签和边界</li><li>3. 写明具体问题与定位</li><li>4. 退回返修或确认通过</li></ul><p class="helper">意见可以指向对象 ID、视频帧号或音频时间段。操作记录会随作业包导出。</p></div>'}</div>`;
 if(['image','video'].includes(selected?.type))mediaURL(selected,app.store).then(u=>{const im=$(selected.type==='video'?'#review-video':'#review-image');if(im)im.src=u}).catch(()=>{});
 if(selected?.customLabels?.length){const names=new Map(selected.customLabels.map(l=>[l.id,l.name]));document.querySelectorAll('.review-descriptions p').forEach(p=>{for(const node of p.childNodes){if(node.nodeType!==Node.TEXT_NODE)continue;node.textContent=node.textContent.replace(/^(#\d+ )([^：]+)(：)/,(whole,prefix,id,colon)=>names.has(id)?prefix+names.get(id)+colon:whole)}})}
}
function reviewForm(t){return `<aside class="panel review-form"><div class="review-preview">${t.type==='image'?'<img id="review-image" alt="当前复核素材">':t.type==='video'?'<video id="review-video" controls preload="metadata" aria-label="复核视频" style="width:100%;max-height:200px"></video>':icon(t.type,48)}</div><div class="between"><h3>${esc(t.name)}</h3>${status(t)}</div><p class="review-detail" style="margin-top:12px">${TYPE_NAMES[t.type]} · ${countAnn(t)} 项标注<br>标注员：${esc(t.originLearner||app.profile.name)}${t.annotation.uncertain?`<br>疑难：${esc(t.annotation.issue)}`:''}</p><div class="flex" style="margin-top:15px;flex-wrap:wrap"><button class="btn secondary small" data-action="open-task" data-id="${esc(t.id)}">查看原素材</button><button class="btn ghost small" data-action="history" data-id="${esc(t.id)}">操作记录</button></div>${['image','video'].includes(t.type)&&(t.type==='image'||t.annotation.tracks.length||t.annotation.description)?`<div class="review-descriptions"><strong>对象描述</strong>${t.annotation.description?`<p>${esc(t.annotation.description)}</p>`:''}${(t.type==='image'?t.annotation.boxes:t.annotation.tracks).map((o,i)=>`<p>#${i+1} ${esc(LABELS.find(l=>l.id===o.label)?.name||o.label)}：${esc(o.description||'未填写描述')}</p>`).join('')||(!t.annotation.description?'<p>未填写描述</p>':'')}</div>`:''}${t.type==='video'&&t.annotation.actions?.length?`<div class="review-descriptions"><strong>动作片段</strong>${t.annotation.actions.map(s=>`<p>${time(s.start)}–${time(s.end)} · ${esc(s.actor)} · ${esc(s.action)} · ${esc(s.object)}${s.uncertain?' · 需复核':''}<br>${esc(s.description)}</p>`).join('')}</div>`:''}<label for="reviewer">复核人</label><input id="reviewer" value="${esc(app.reviewer||'项目复核')}" placeholder="填写复核人"><label for="review-comment">复核意见与定位</label><textarea id="review-comment" rows="4" placeholder="例：瓶子 #1 右边界过松，或视频 F24 发生漏标。">${esc(t.review?.comment||'')}</textarea><div class="flex" style="margin-top:17px"><button class="btn danger small" data-action="review-decision" data-value="rework">退回返修</button><button class="btn primary small" data-action="review-decision" data-value="approved">${icon('check',13)}通过</button></div></aside>`}
async function reviewDecision(value){const t=copy(app.tasks.find(t=>t.id===app.reviewId));if(!t)return;const reviewer=$('#reviewer').value.trim(),comment=$('#review-comment').value.trim();if(!reviewer){toast('请填写复核人。',true);return}if(value==='rework'&&!comment){toast('退回时请填写具体问题和定位。',true);return}t.status=value;t.review={by:reviewer,comment,at:new Date().toISOString()};t.history.push({at:t.review.at,action:value==='approved'?'approve':'return',by:reviewer,note:comment||'复核通过'});t.updatedAt=t.review.at;app.reviewer=reviewer;await app.store.setting('reviewer',reviewer);await persistTask(t);renderReview();toast(value==='approved'?'已记录复核通过。':'已退回返修，原意见已保留在操作记录中。')}
function historyModal(id){const t=app.tasks.find(x=>x.id===id);modal('标注与复核记录',`<p>${esc(t.name)} · ${esc(t.id)}</p>${t.history?.length?t.history.map(h=>`<div class="history-item"><small>${dateTime(h.at)} ${esc(h.by||'')}</small>${esc(h.note||h.action)}</div>`).join(''):'<p>暂无提交或复核记录。</p>'}`,`<button class="btn primary" data-action="close-modal">关闭</button>`)}
function exportTasks(){return app.exportProject&&app.exportProject!=='all'?tasksFor(app.exportProject):app.tasks}
function renderExports(){const ts=exportTasks(),submitted=ts.filter(done).length,errors=ts.filter(t=>done(t)&&validateTask(t).length).length;$('#content').innerHTML=pageHeader('PACKAGE & HANDOFF','把标注整理成可复核的作业','导出结果、原素材和复核记录。复核人在另一台电脑导入 ZIP，即可继续检查与返修。',`<button class="btn secondary" data-action="import-package">${icon('upload',15)}导入作业包</button>`)+`<div class="export-layout"><section class="panel export-main"><div class="between"><h3>导出范围</h3><select id="export-project" aria-label="选择导出项目"><option value="all">全部项目</option>${PROJECTS.filter(p=>tasksFor(p.id).length).map(p=>`<option value="${p.id}" ${app.exportProject===p.id?'selected':''}>${p.title}</option>`).join('')}</select></div><div class="divider"></div>${[['zip','folder','完整作业包 ZIP','包含标注、素材、标注员信息和复核记录，用于移交与备份。','导出作业包'],['json','text','结构化结果 JSON','完整标注结构与操作记录，不附带媒体文件。可用于结果核对。','导出 JSON'],['csv','grid','标注明细 CSV','图像目标、视频关键帧、音频转写、文字实体与对象描述。','导出 CSV'],['actions','video','动作片段与字幕','仅导出动作时间、人物、文字及 SRT/WebVTT 字幕，不含视频。','导出动作包'],['coco','image','图像结果 COCO','图像类别、目标框与多边形；对象描述在 attributes.description 扩展属性中。','导出 COCO']].map(([id,ic,title,desc,cta])=>`<div class="export-option"><span class="export-icon">${icon(ic,22)}</span><div class="description"><h3>${title}</h3><p>${desc}</p></div><button class="btn ${id==='zip'?'primary':'secondary'} small" data-action="export" data-format="${id}">${cta}${icon('download',13)}</button></div>`).join('')}</section><aside class="panel export-side"><span class="eyebrow">HANDOFF CHECKLIST</span><div class="summary-number">${submitted}<small> / ${ts.length} 个已提交</small></div><div class="progress"><i style="width:${pct(submitted,ts.length)}%"></i></div><ul class="check-list"><li>${icon('check',15)}当前范围 ${ts.length} 个素材，${ts.filter(t=>t.status==='approved').length} 个已通过</li><li>${icon('review',15)}${ts.filter(t=>t.status==='rework').length} 个待返修，${ts.filter(t=>t.annotation.uncertain).length} 个疑难样本</li><li>${icon('user',15)}${esc(app.profile.name)} · ${esc(app.profile.number||'编号未填写')}</li></ul>${errors?`<div class="notice">${errors} 个已提交样本未通过格式检查，请在工作区修正后再交付。</div>`:''}<div class="notice">可以导出未完成的草稿作为备份。正式交付前，请确认任务状态、素材对应与复核意见。</div><p class="helper">本平台不自动发送作业。浏览器数据彼此独立，清理站点数据前请先备份 ZIP。</p><button class="btn ghost small" style="margin-top:10px" data-action="profile">编辑标注员信息${icon('arrow',13)}</button></aside></div>`;}
async function doExport(format){try{await flush();const ts=exportTasks();if(!ts.length){toast('当前范围没有可导出的素材。');return}const date=new Date().toISOString().slice(0,10),name=`标注作业_${app.profile.name||'学员'}_${date}`;
 if(format==='zip'){busy('正在整理作业包','正在读取原始素材与标注记录，请稍候。');const blob=await exportZip(ts,app.profile,[],null,app.store);unbusy();download(blob,name+'.zip')}
 else if(format==='actions')download(exportActions(ts),name+'_动作片段.zip');
 else if(format==='json')download(new Blob([JSON.stringify(manifest(ts,app.profile,[],null),null,2)],{type:'application/json'}),name+'.json');
 else if(format==='csv')download(new Blob([csv(ts)],{type:'text/csv;charset=utf-8'}),name+'.csv');
 else{if(!ts.some(t=>t.type==='image')){toast('当前范围没有图像素材。');return}download(new Blob([JSON.stringify(coco(ts),null,2)],{type:'application/json'}),name+'_COCO.json')}
 toast('已生成下载文件，请保存后再交给复核人。')
 }catch(e){unbusy();toast('导出失败：'+e.message,true)}}
async function importFiles(files){if(!files.length)return;const supported=[...files].filter(f=>/^(image\/(png|jpeg|webp)|video\/(mp4|webm)|audio\/)/.test(f.type)||f.name.toLowerCase().endsWith('.txt'));if(!supported.length){toast('请选择 PNG/JPG/WebP、MP4/WebM、音频或 TXT 文件。',true);return}if(supported.some(f=>f.size>100*1024*1024)){toast('单个素材不能超过 100 MB。',true);return}if(supported.length>100){toast('一次最多导入 100 个素材。',true);return}
 try{busy('正在导入素材','文件仅保存在当前浏览器，视频可直接做动作片段标注；逐帧追踪需确认固定帧率。');const tasks=[];for(const f of supported){const type=f.name.toLowerCase().endsWith('.txt')?'text':f.type.split('/')[0],id=uid('custom');const t={id,project:'imports',type,name:f.name,width:1200,height:760,status:'new',annotation:blankAnnotation(),history:[],updatedAt:null};if(type==='text'){t.text=await f.text();t.goal='intent';if(t.text.length>100000)throw new Error('TXT 请控制在 10 万字符以内。')}else{const bid=uid('blob');await app.store.putBlob(bid,f);t.blobId=bid;if(type==='video'){t.fps=null;t.goal='actions';t.labelIds=['person','hand','object','ball']}}tasks.push(t)}await app.store.putTasks(tasks);app.tasks.push(...tasks);unbusy();await navigate('project',{project:'imports',statusFilter:'all',typeFilter:'all',search:''});toast(`已导入 ${tasks.length} 个素材。${files.length>supported.length?'部分不支持的格式已跳过。':''}`)}catch(e){unbusy();toast('导入失败：'+e.message,true)}}
async function loadPackage(file){if(!file)return;try{busy('正在导入作业包','读取素材、标注与复核记录，不覆盖当前标注。');const allowed=new Set(app.tasks.filter(t=>t.src&&!t.blobId).flatMap(t=>[t.src,...(t.sensorSrc?[t.sensorSrc]:[])]));const result=await importPackage(file,app.store,allowed);app.tasks.push(...result.tasks);unbusy();await navigate('review',{reviewFilter:'all',reviewId:result.tasks.find(t=>t.status==='submitted')?.id||result.tasks[0]?.id});toast(`已导入 ${result.count} 个作业样本，原有标注已保留。`)}catch(e){unbusy();toast('作业包导入失败：'+e.message,true)}}

function profileModal(){modal('标注员信息',`<p>信息只保存在当前浏览器，并随作业包导出，方便复核人识别提交人。</p><label for="profile-name">姓名或昵称</label><input id="profile-name" maxlength="40" value="${esc(app.profile.name)}"><div class="form-grid"><div><label for="profile-number">编号</label><input id="profile-number" maxlength="40" value="${esc(app.profile.number)}"></div><div><label for="profile-group">项目或小组</label><input id="profile-group" maxlength="60" value="${esc(app.profile.group)}"></div></div>`,`<button class="btn secondary" data-action="close-modal">取消</button><button class="btn primary" data-action="save-profile">保存信息</button>`)}
function guideModal(){modal('标注工坊操作指南',`<p>导入自己的素材后即可开始。素材和标注自动保存在当前浏览器，无需账号。</p><div class="help-grid">${[['image','图像','先选类别，再拖动画框。V 选择，B 矩形，P 多边形；双击或 Enter 闭合。支持自定义类别、遮挡与对象描述。'],['video','视频','在动作时间轴拖动创建片段，填写谁做了什么。I/O 标记起止，左右键逐帧；物体轨迹模式支持目标框与关键帧。'],['audio','音频','拖动波形创建片段，填写转写与说话人。支持选段回放、循环和速度调节。'],['text','文字','选择意图；选中原文，再点日期、时间或地点添加实体。标注保留原文与字符位置。']].map(([ic,n,s])=>`<div class="help-item">${icon(ic,19)}<strong>${n}标注</strong><p>${s}</p></div>`).join('')}</div><h3>质量复核与返修</h3><p>完成后提交到本地复核列表，在“质量复核”填写意见，退回或通过。返修、提交和复核历史会保留。跨电脑复核时先导出完整 ZIP，由复核人导入。</p><h3>结果与素材交付</h3><p>完整 ZIP 包含素材、标注和复核记录。JSON、CSV、COCO 及动作字幕不附带媒体。作业包支持本平台导出的未压缩 ZIP，单包不超过 250 MB；导入素材每个不超过 100 MB，一次最多 100 个。</p><h3>保存与考核</h3><p>浏览器之间的数据独立，清理站点数据前请导出 ZIP 备份。实操考核需要单独配置私有题库和 Python 服务，由考核组织者提供入口。</p>`,`<button class="btn primary" data-action="close-modal">开始标注</button>`,true)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();if(b.disabled)return;const a=b.dataset.action;
 try{
  if(a==='close-modal'){closeModal();return}if(a==='menu'){$('#sidebar').classList.toggle('open');return}
  if(a==='nav'&&b.dataset.page==='assessment'){await flush();location.assign('./exam.html');return}if(a==='nav'){await navigate(b.dataset.page);return}if(a==='guide'){guideModal();return}if(a==='profile'){profileModal();return}if(a==='standards'){standardsModal();return}
  if(a==='save-profile'){const name=$('#profile-name').value.trim();if(!name){toast('请填写姓名或昵称。',true);return}app.profile={name,number:$('#profile-number').value.trim(),group:$('#profile-group').value.trim()};await app.store.setting('profile',app.profile);closeModal();await navigate(app.page);toast('标注员信息已保存。');return}
  if(a==='project'){await navigate('project',{project:b.dataset.project,statusFilter:'all',typeFilter:'all',search:''});return}
  if(a==='status-filter'){app.statusFilter=b.dataset.value;renderProject();return}
  if(a==='continue'){const t=app.tasks.find(t=>t.id===app.taskId)||app.tasks.find(t=>t.status==='draft'||t.status==='rework')||app.tasks[0];if(t)await navigate('workbench',{taskId:t.id});else $('#media-input').click();return}
  if(a==='open-task'){await navigate('workbench',{taskId:b.dataset.id});return}
  if(a==='open-project-first'){const t=filteredTasks().find(t=>!done(t))||filteredTasks()[0];if(t)await navigate('workbench',{taskId:t.id});else toast('当前筛选条件下没有素材。');return}
  if(a==='prev-task'||a==='next-task'){const ts=tasksFor(app.project),idx=ts.findIndex(t=>t.id===app.taskId),next=ts[idx+(a==='next-task'?1:-1)];if(next)await navigate('workbench',{taskId:next.id});return}
  if(a==='save-task'){if(editor){await flush();toast('当前标注已保存到本地浏览器。')}return}
  if(a==='submit-task'){await submitTask();return}
  if(a==='withdraw'){confirmModal('撤回并继续编辑','这会把当前标注改回草稿，复核与提交历史会继续保留。',async()=>{const t=copy(editor.task);t.status='draft';t.history.push({at:new Date().toISOString(),action:'withdraw',by:app.profile.name,note:'撤回并继续编辑'});await persistTask(t);await navigate('workbench',{taskId:t.id})});return}
  if(a==='review-filter'){app.reviewFilter=b.dataset.value;renderReview();return}if(a==='review-select'){app.reviewId=b.dataset.id;renderReview();return}if(a==='review-decision'){await reviewDecision(b.dataset.value);return}if(a==='history'){historyModal(b.dataset.id);return}
  if(a==='import-media'){$('#media-input').click();return}if(a==='import-package'){$('#package-input').click();return}if(a==='export'){await doExport(b.dataset.format);return}
 }catch(err){toast(err.message||'操作未完成，请重试。',true)}
});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='media-input'){await importFiles(el.files);el.value=''}if(el.id==='package-input'){await loadPackage(el.files[0]);el.value=''}
 if(el.id==='type-filter'){app.typeFilter=el.value;renderProject()}if(el.id==='export-project'){app.exportProject=el.value;renderExports()}
 }catch(err){toast(err.message,true)}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){app.search=e.target.value;const rows=filteredTasks();$('#project-table').innerHTML=rows.length?taskTable(rows):'<div class="empty">没有符合条件的素材。</div>'}});
document.addEventListener('keydown',e=>{if($('#modal-root').children.length){if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const els=[...$('#modal-root').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')];const i=els.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&i===els.length-1){e.preventDefault();els[0]?.focus()}}return}if(e.key==='Enter'&&e.target.matches('[role="button"][data-ed]'))e.target.click();else editor?.hotkey(e)});
window.addEventListener('beforeunload',e=>{if(app.saveError||app.pending.size){e.preventDefault();e.returnValue=''}});
async function init(){try{await app.store.init();const [tasks,profile,lastTask,reviewer]=await Promise.all([app.store.all(),app.store.getSetting('profile'),app.store.getSetting('lastTask'),app.store.getSetting('reviewer')]);app.tasks=tasks;app.profile=profile||app.profile;app.taskId=lastTask||null;app.reviewer=reviewer||null;const requested=new URLSearchParams(location.search).get('task');if(requested&&app.tasks.some(t=>t.id===requested))await navigate('workbench',{taskId:requested});else await navigate('dashboard')}catch(e){$('#app').innerHTML=`<div class="boot"><span class="brand-symbol"></span><h1>标注空间暂时无法打开</h1><p>${esc(e.message)}</p><p>请允许浏览器使用本地存储，然后刷新。</p><button class="btn primary" onclick="location.reload()">重新加载</button></div>`;console.error(e)}}

init();
